    {
        if constexpr (sizeof(T) == 1)
        {
            return static_cast<T>(p[0]);
        }
        else if constexpr (sizeof(T) == 2)
        {
            if (size >= 2)
            {
                FIT_UINT16 v;
                std::memcpy(&v, p, 2);
                return static_cast<T>(v);
            }
            return static_cast<T>(p[0]);
        }
        else if constexpr (sizeof(T) == 4)
        {
            if (size >= 4)
            {
                FIT_UINT32 v;
                std::memcpy(&v, p, 4);
                return static_cast<T>(v);
            }
            if (size >= 2)
            {
                FIT_UINT16 v;
                std::memcpy(&v, p, 2);
                return static_cast<T>(v);
            }
            return static_cast<T>(p[0]);
        }
        else if constexpr (sizeof(T) == 8)
        {
            if (size >= 8)
            {
                FIT_UINT64 v;
                std::memcpy(&v, p, 8);
                return static_cast<T>(v);
            }
            if (size >= 4)
            {
