                std::memcpy(&v, p, 4);
                return static_cast<T>(v);
            }
            if (size >= 2)
            {
                FIT_UINT16 v;
                std::memcpy(&v, p, 2);
                return static_cast<T>(v);
            }
            return static_cast<T>(p[0]);
        }
    }

    FIT_UINT64 rv = 0;

